<script setup lang="ts">
/**
 * BrandMark - the logo mark as an inline SVG that follows data-theme via CSS variables.
 * Colours: --color-brand-mark (strokes/nodes) and --color-brand-mark-accent (amber pair), defined in 03-tokens.css.
 * The name is NOT in the SVG: render the wordmark as live text from BRAND.wordmark next to it (see README).
 * Geometry mirrors logo/mark-*.svg (generated by tools/gen-logo.py); numbers here are illustration geometry, not design tokens.
 *
 * Props
 *  - size:    number (px) | string (any CSS length). Default 32. Below 28px the simplified "compact" geometry is used automatically.
 *  - variant: 'auto' (navy/ink + amber, theme-aware) | 'mono' (currentColor only; the amber pair becomes hollow rings so it stays distinct)
 *  - title:   when set the SVG is role="img" with that accessible name; otherwise it is aria-hidden (decorative, e.g. next to the wordmark).
 */
import { computed } from 'vue'

const props = withDefaults(defineProps<{ size?: number | string; variant?: 'auto' | 'mono'; title?: string }>(), {
  size: 32,
  variant: 'auto',
  title: undefined,
})

const px = computed(() => (typeof props.size === 'number' ? props.size : null))
const cssSize = computed(() => (typeof props.size === 'number' ? `${props.size}px` : props.size))
const compact = computed(() => px.value !== null && px.value < 28)
const mono = computed(() => props.variant === 'mono')

// ---- full geometry, 512 grid ----
const HEX_FULL = 'M235 40.12A42 42 0 0 1 277 40.12L432.45 129.88A42 42 0 0 1 453.45 166.25L453.45 345.75A42 42 0 0 1 432.45 382.12L277 471.88A42 42 0 0 1 235 471.88L79.55 382.12A42 42 0 0 1 58.55 345.75L58.55 166.25A42 42 0 0 1 79.55 129.88Z'
const C = 256, NR = 18, ES = 5.5
const P = { C: [C, C], UL: [178, 185], UR: [334, 185], LL: [178, 327], LR: [334, 327], L: [101, C], R: [411, C], T: [C, 96], B: [C, 416] } as const
const DARK_EDGES = [['C', 'UL'], ['C', 'UR'], ['C', 'LL'], ['C', 'LR'], ['UL', 'L'], ['LL', 'L'], ['UR', 'R'], ['LR', 'R']] as const
const AMBER_EDGES = [['T', 'UL'], ['T', 'UR'], ['B', 'LL'], ['B', 'LR']] as const
const RING_W = ES * 1.3
type K = keyof typeof P
function seg(a: K, b: K, shortenA = 0) {
  let [x1, y1] = P[a]; const [x2, y2] = P[b]
  if (shortenA) { const L = Math.hypot(x2 - x1, y2 - y1); x1 += ((x2 - x1) / L) * shortenA; y1 += ((y2 - y1) / L) * shortenA }
  return { x1, y1, x2, y2 }
}
const darkEdges = DARK_EDGES.map(([a, b]) => seg(a, b))
const amberEdges = computed(() => AMBER_EDGES.map(([a, b]) => seg(a, b, mono.value ? NR - RING_W / 2 + 0.2 : 0)))
const darkNodes = (['C', 'UL', 'UR', 'LL', 'LR', 'L', 'R'] as K[]).map((k) => P[k])
const pairNodes = (['T', 'B'] as K[]).map((k) => P[k])

// ---- compact geometry, 64 grid ----
const HEX_COMPACT = 'M28.8 5.25A6.4 6.4 0 0 1 35.2 5.25L53.57 15.85A6.4 6.4 0 0 1 56.77 21.4L56.77 42.6A6.4 6.4 0 0 1 53.57 48.15L35.2 58.75A6.4 6.4 0 0 1 28.8 58.75L10.43 48.15A6.4 6.4 0 0 1 7.23 42.6L7.23 21.4A6.4 6.4 0 0 1 10.43 15.85Z'
const CP = { T: [32, 15], B: [32, 49], L: [17, 32], R: [47, 32], C: [32, 32] } as const
const CAMBER = [['T', 'L'], ['T', 'R'], ['B', 'L'], ['B', 'R']] as const
</script>

<template>
  <svg
    class="brand-mark"
    :class="{ 'is-mono': mono }"
    :viewBox="compact ? '0 0 64 64' : '0 0 512 512'"
    :width="cssSize"
    :height="cssSize"
    :role="title ? 'img' : undefined"
    :aria-hidden="title ? undefined : 'true'"
    focusable="false"
  >
    <title v-if="title">{{ title }}</title>

    <template v-if="compact">
      <path :d="HEX_COMPACT" class="stroke" stroke-width="4.4" stroke-linejoin="round" fill="none" />
      <line :x1="CP.L[0]" :y1="CP.L[1]" :x2="CP.C[0]" :y2="CP.C[1]" class="stroke" stroke-width="2.4" stroke-linecap="round" />
      <line :x1="CP.C[0]" :y1="CP.C[1]" :x2="CP.R[0]" :y2="CP.R[1]" class="stroke" stroke-width="2.4" stroke-linecap="round" />
      <line v-for="([a, b], i) in CAMBER" :key="i" :x1="CP[a][0]" :y1="CP[a][1]" :x2="CP[b][0]" :y2="CP[b][1]" class="stroke accent" stroke-width="2.8" stroke-linecap="round" />
      <circle :cx="CP.C[0]" :cy="CP.C[1]" r="4.6" class="fill" />
      <circle :cx="CP.L[0]" :cy="CP.L[1]" r="4.2" class="fill" />
      <circle :cx="CP.R[0]" :cy="CP.R[1]" r="4.2" class="fill" />
      <template v-for="k in (['T', 'B'] as const)" :key="k">
        <circle v-if="!mono" :cx="CP[k][0]" :cy="CP[k][1]" r="4.6" class="fill accent" />
        <circle v-else :cx="CP[k][0]" :cy="CP[k][1]" r="3.4" class="stroke accent" fill="none" stroke-width="2.2" />
      </template>
    </template>

    <template v-else>
      <path :d="HEX_FULL" class="stroke" stroke-width="14" stroke-linejoin="round" fill="none" />
      <g :stroke-width="ES" stroke-linecap="round">
        <line v-for="(s, i) in darkEdges" :key="`d${i}`" v-bind="s" class="stroke" />
        <line v-for="(s, i) in amberEdges" :key="`a${i}`" v-bind="s" class="stroke accent" />
      </g>
      <circle v-for="(n, i) in darkNodes" :key="`n${i}`" :cx="n[0]" :cy="n[1]" :r="NR" class="fill" />
      <template v-for="(n, i) in pairNodes" :key="`p${i}`">
        <circle v-if="!mono" :cx="n[0]" :cy="n[1]" :r="NR" class="fill accent" />
        <circle v-else :cx="n[0]" :cy="n[1]" :r="NR - RING_W / 2" class="stroke accent" fill="none" :stroke-width="RING_W" />
      </template>
    </template>
  </svg>
</template>

<style scoped>
.brand-mark {
  display: inline-block;
  flex: none;
  color: var(--color-brand-mark);
}
.stroke { stroke: var(--color-brand-mark); }
.fill { fill: var(--color-brand-mark); }
.accent.stroke { stroke: var(--color-brand-mark-accent); }
.accent.fill { fill: var(--color-brand-mark-accent); }
/* mono: everything follows currentColor (set `color` on the parent) */
.is-mono { color: inherit; }
.is-mono .stroke, .is-mono .accent.stroke { stroke: currentColor; }
.is-mono .fill, .is-mono .accent.fill { fill: currentColor; }
</style>
